package cn.zhuatech.siem;import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.http.MediaType;import org.springframework.test.web.servlet.*;import java.util.regex.*;import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.httpBasic;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest @AutoConfigureMockMvc class DeepSiemOpsTests{@Autowired MockMvc mvc;String hash="aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa";
 @Test void detectedEventRunsThroughIncidentResponse()throws Exception{long s=source("SRC-1");admin("/api/admin/siem-ops/sources/"+s+"/activate","{}");rule("R-1",70);long i=idField(post("/api/siem-ops/sources/"+s+"/events",event("EV-1",90)).andExpect(jsonPath("$.data.matchedRule").isString()).andReturn(),"incidentId");post("/api/siem-ops/incidents/"+i+"/assign","{\"assignee\":\"安全分析师\"}");post("/api/siem-ops/incidents/"+i+"/investigate","{\"note\":\"确认异常登录并横向移动\",\"evidenceHash\":\""+hash+"\"}");post("/api/siem-ops/incidents/"+i+"/respond","{\"action\":\"隔离终端并重置账号\"}");post("/api/siem-ops/incidents/"+i+"/recover","{}");admin("/api/admin/siem-ops/incidents/"+i+"/close","{\"note\":\"业务恢复且复盘完成\"}").andExpect(jsonPath("$.data.status").value("CLOSED"));}
 @Test void inactiveSourceAndLowSeverityDoNotCreateIncident()throws Exception{long s=source("SRC-2");post("/api/siem-ops/sources/"+s+"/events",event("EV-X",90)).andExpect(status().isConflict());admin("/api/admin/siem-ops/sources/"+s+"/activate","{}");rule("R-2",80);post("/api/siem-ops/sources/"+s+"/events",event("EV-2",30)).andExpect(status().isOk()).andExpect(jsonPath("$.data.incidentId").doesNotExist());}
 @Test void duplicateEventAndInvalidEvidenceAreRejected()throws Exception{long s=source("SRC-3");admin("/api/admin/siem-ops/sources/"+s+"/activate","{}");rule("R-3",50);post("/api/siem-ops/sources/"+s+"/events",event("EV-3",90));post("/api/siem-ops/sources/"+s+"/events",event("EV-3",90)).andExpect(status().isConflict());}
 long source(String n)throws Exception{return id(post("/api/siem-ops/sources","{\"organizationCode\":\"ZH-SH\",\"sourceCode\":\""+n+"\",\"name\":\"终端检测平台\",\"sourceType\":\"EDR\"}").andReturn());}void rule(String n,int score)throws Exception{admin("/api/admin/siem-ops/rules","{\"organizationCode\":\"ZH-SH\",\"ruleCode\":\""+n+"\",\"name\":\"高风险异常登录\",\"eventType\":\"SUSPICIOUS_LOGIN\",\"minimumSeverity\":"+score+",\"incidentSeverity\":\"HIGH\"}");}String event(String n,int score){return "{\"eventId\":\""+n+"\",\"eventType\":\"SUSPICIOUS_LOGIN\",\"severityScore\":"+score+",\"principal\":\"user-a\",\"asset\":\"endpoint-001\",\"summary\":\"异地高频登录\",\"occurredAt\":\"2026-09-01T10:00:00\"}";}ResultActions post(String u,String b)throws Exception{return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(u).with(httpBasic("operator","operator123")).contentType(MediaType.APPLICATION_JSON).content(b));}ResultActions admin(String u,String b)throws Exception{return mvc.perform(org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post(u).with(httpBasic("admin","admin123")).contentType(MediaType.APPLICATION_JSON).content(b));}long id(MvcResult r)throws Exception{return idField(r,"id");}long idField(MvcResult r,String f)throws Exception{var m=Pattern.compile("\""+f+"\":(\\d+)").matcher(r.getResponse().getContentAsString());Assertions.assertTrue(m.find());return Long.parseLong(m.group(1));}}
